import { classifyDocument } from './document-classifier.mjs';
import {CURRICULUM_KEY, curriculumScope, inspectCurriculumPdf, displaySource} from './curriculum-registry.mjs';
import { SUBJECTS, GROUPS, normalizeSubject, normalizeGroup, gradeLabel } from './academic-fields.mjs';
import * as pdfjs from './vendor/pdf.mjs';
pdfjs.GlobalWorkerOptions.workerSrc = new URL('./vendor/pdf.worker.mjs', import.meta.url).href;
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const DAY=86400000, KEY='ijr-planning-lab-v1', states=['cargada','en análisis por IA','en revisión','con ajustes','aprobada','devuelta'];
const stamp=()=>new Date().toISOString(), fmt=s=>new Date(s).toLocaleString('es-CO',{timeZone:'America/Bogota',dateStyle:'medium',timeStyle:'short'});
const demo={id:'PL-001',title:'Áreas que habitamos',area:'Geometría',grade:'8',period:'III',author:'Docente de demostración',state:'en revisión',submitted:new Date(Date.now()-2*DAY).toISOString(),version:1,file:null,pages:[],notes:[],report:null,events:[]};
demo.events=[{at:demo.submitted,actor:'Docente · demo',type:'Entrega recibida',text:'Versión 1. Inicio del plazo global de ocho días.'},{at:new Date(new Date(demo.submitted).getTime()+300000).toISOString(),actor:'Sistema · demo',type:'En revisión',text:'Ejemplo preparado para explorar la revisión humana. No se ha ejecutado un modelo de IA.'}];
let db;try{db=JSON.parse(localStorage.getItem(KEY));}catch{}if(!db?.records)db={records:[demo],selected:'PL-001',role:'Coordinador académico'};
let activePdf=null,sourcePdf=null,activeCurriculumPdf=null,activeCurriculumHash=null,renderSeq=0,pendingAnchor=null,sourceTab='pei',linkingNoteIndex=null;
let curriculumRegistry={};try{curriculumRegistry=JSON.parse(localStorage.getItem(CURRICULUM_KEY))||{};}catch{curriculumRegistry={};}
function mallaFor(r){return curriculumRegistry[curriculumScope(r.grade,r.area,r.period)]?.active||null;}
function saveCurriculum(){localStorage.setItem(CURRICULUM_KEY,JSON.stringify(curriculumRegistry));}
const rec=()=>db.records.find(r=>r.id===db.selected)||db.records[0];
const save=()=>{try{localStorage.setItem(KEY,JSON.stringify(db));}catch{toast('No hay espacio de almacenamiento. Exporta el expediente antes de cerrar.');}};
const event=(r,type,text,actor=db.role)=>{r.events.push({at:stamp(),actor,type,text,version:r.version});save();};
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',5000);}
function deadline(r){return new Date(r.submitted).getTime()+8*DAY;}
function remaining(r){let n=deadline(r)-Date.now();return n<0?'Vencido':`${Math.floor(n/DAY)} d ${Math.floor(n%DAY/3600000)} h`;}
function badge(r){return `<span class="badge ${r.state==='aprobada'?'green':r.state==='devuelta'?'red':'amber'}">${esc(r.state)}</span>`;}
function title(eyebrow,h,sub,button=''){return `<div class="title-row"><div><p class="eyebrow">${eyebrow}</p><h1>${h}</h1><p>${sub}</p></div>${button}</div>`;}
function demoBanner(){return '<div class="banner"><strong>Laboratorio funcional</strong><span>Guardado en este navegador. Usa documentos de prueba sin datos personales. No hay autenticación ni sincronización institucional activa.</span></div>';}
function stages(r){return `<div class="steps">${states.map((s,i)=>`<span class="${r.state===s?'current':''}">${String(i+1).padStart(2,'0')} ${s}</span>`).join('')}</div>`;}
const pipeline=[['Recepción y análisis','Día 0–1 · validación, extracción y análisis'],['Revisión y primer retorno','Hasta día 5 · observaciones del coordinador'],['Ajustes del docente','Hasta día 7 · conserva el plazo original'],['Cierre o devolución motivada','Hasta día 8 · decisión y entrega registrada']];
function stats(){const open=db.records.filter(r=>!['aprobada','devuelta'].includes(r.state));return `<div class="stats"><div class="stat"><div class="label">Planeaciones recibidas</div><div class="value">${db.records.length.toString().padStart(2,'0')}</div><div class="note">Expedientes de este navegador</div></div><div class="stat"><div class="label">Pendientes de decisión</div><div class="value">${open.length.toString().padStart(2,'0')}</div><div class="note">Revisión humana requerida</div></div><div class="stat"><div class="label">Fuera de plazo</div><div class="value">${db.records.filter(r=>!r.closed&&Date.now()>deadline(r)).length.toString().padStart(2,'0')}</div><div class="note">No se aprueban automáticamente</div></div><div class="stat accent"><div class="label">Plazo máximo por ciclo</div><div class="value">08 <span style="font-size:16px">días</span></div><div class="note">Calendario · sin reinicio por ajustes</div></div></div>`;}
function inbox(){return title('ACOMPAÑAMIENTO PEDAGÓGICO','Cada planeación, un mejor aprendizaje.','Revisa la coherencia curricular, conversa sobre los ajustes y acompaña cada entrega hasta su cierre.','<a class="btn primary" href="#cargar">＋ Nueva planeación</a>')+demoBanner()+stats()+`<div class="two"><section class="card"><div class="card-head"><h2>Bandeja de planeaciones</h2><span class="subtle">${esc(db.role)}</span></div><div class="search-row"><input id="search" aria-label="Buscar planeación" placeholder="Buscar por título o asignatura…"><select id="stateFilter" aria-label="Filtrar estado"><option value="">Todos los estados</option>${states.map(s=>`<option>${s}</option>`).join('')}</select></div><div id="recordTable"></div><div class="callout">El informe orienta la revisión. La decisión pedagógica siempre corresponde al coordinador.</div></section><aside class="card"><div class="card-head"><h2>Un ciclo de ocho días</h2><span>◷</span></div>${pipeline.map((s,i)=>`<div class="stage"><span class="num">${i+1}</span><div><strong>${s[0]}</strong><p>${s[1]}</p></div></div>`).join('')}<div class="callout">Distribución de tiempos propuesta; requiere validación de la institución.</div><a href="#tiempos" class="btn">Ver tiempos y avisos ↗</a></aside></div>`;}
function table(){const q=($('#search')?.value||'').toLowerCase(),f=$('#stateFilter')?.value;const rs=db.records.filter(r=>(r.title+' '+r.area+' '+gradeLabel(r.grade,r.group)).toLowerCase().includes(q)&&(!f||r.state===f));$('#recordTable').innerHTML=`<div class="table-wrap"><table><thead><tr><th>Planeación</th><th>Estado</th><th>Tiempo restante</th><th></th></tr></thead><tbody>${rs.map(r=>`<tr><td><strong>${esc(r.title)}</strong><small>${esc(r.area)} · Grado ${esc(gradeLabel(r.grade,r.group))} · Período ${esc(r.period)} · v${r.version}</small></td><td>${badge(r)}</td><td><strong data-clock="${r.id}">${r.closed?'Ciclo cerrado':remaining(r)}</strong><small>${r.closed?fmt(r.closed):'Límite: '+fmt(deadline(r))}</small></td><td><button class="btn small" data-open="${r.id}">Revisar ↗</button></td></tr>`).join('')||'<tr><td colspan="4" class="empty">No hay planeaciones con este filtro.</td></tr>'}</tbody></table></div>`;}
function upload(){return title('01 · ENTREGA DOCENTE','Comparte tu planeación.','Selecciona grado, área y período. El PDF permanece en este dispositivo en la demostración.')+demoBanner()+`<div class="two"><form class="card form-grid" id="uploadForm"><div class="full"><label for="planTitle">Título de la planeación</label><input id="planTitle" required maxlength="120" placeholder="Ej. Áreas y perímetros en nuestro entorno"></div><div><label for="grade">Grado</label><select id="grade">${Array.from({length:11},(_,i)=>`<option ${i===7?'selected':''}>${i+1}</option>`).join('')}</select></div><div><label for="group">Grupo</label><select id="group"><option value="">Sin grupo específico</option>${GROUPS.map(g=>`<option value="${g}">${g}</option>`).join('')}</select></div><div><label for="area">Asignatura o área</label><select id="area" required>${SUBJECTS.map(s=>`<option value="${esc(s)}" ${s==='Geometría'?'selected':''}>${esc(s)}</option>`).join('')}<option value="Otra asignatura">Otra asignatura…</option></select></div><div id="otherAreaWrap" class="full" hidden><label for="otherArea">Nombre de otra asignatura</label><input id="otherArea" maxlength="80" placeholder="Escribe la asignatura que falta en la lista"></div><div><label for="period">Período</label><select id="period"><option>I</option><option>II</option><option selected>III</option></select></div><div><label for="author">Identificador docente de prueba</label><input id="author" required value="Docente demo" maxlength="80"></div><div class="drop full"><div style="font-size:30px">↑</div><h3>Tu planeación en PDF</h3><p>Hasta 15 MB y 80 páginas · PDF con texto seleccionable.</p><label for="pdfFile" class="sr-only">Archivo PDF</label><input id="pdfFile" type="file" accept="application/pdf,.pdf" required><p id="fileStatus" aria-live="polite"></p><p class="subtle">Antes de registrar el archivo, el navegador comprueba si es una planeación, un cronograma o un artículo científico. Esta detección por reglas no sustituye la revisión humana.</p></div><div class="full"><label><input type="checkbox" id="privacyCheck" required> Confirmo que es una prueba sin nombres, diagnósticos ni datos de estudiantes.</label><p class="subtle">Esta declaración no sustituye la revisión de privacidad. Los PDF escaneados requieren OCR local.</p></div><div class="full actions"><button class="btn primary" id="uploadSubmit">Guardar entrega de prueba →</button><a href="#bandeja" class="btn ghost">Cancelar</a></div></form><aside class="card prose"><p class="eyebrow">ANTES DE ENTREGAR</p><h2>Una revisión con evidencia.</h2><p>Incluye objetivos, contenidos, actividades, evaluación, tiempos y recursos. La alineación deberá contrastarse con las versiones vigentes de malla, plan de área, estándares y PEI.</p><div class="callout">Solo la malla de Geometría 8.º, período III, tiene criterios precargados en este prototipo. Los demás grados y áreas quedarán «sin referencia curricular validada».</div><h3>En producción local</h3><p>Al recibir el archivo, el servidor asignará versión, hash SHA-256 y sello de tiempo. Este será el inicio oficial del reloj.</p><a class="btn" href="docs/pei-extracto-p41.pdf" target="_blank" rel="noopener">Abrir extracto del PEI de prueba ↗</a></aside></div>`;}
const curriculum=`<div class="source-excerpt"><p class="eyebrow">FUENTE REAL · MALLA 2026</p><h3>Geometría 8.º · Período III</h3><p><strong>Ejes:</strong> áreas y perímetros de figuras planas; áreas sombreadas simples y complejas; volúmenes de sólidos pitagóricos y platónicos; área superficial de sólidos.</p><p><strong>Estándar incluido en la malla:</strong> «Calculo y comparo áreas y perímetros de figuras planas utilizando diferentes métodos numéricos».</p><p><strong>Desempeño:</strong> reconoce formas básicas en figuras complejas y emplea la relación adecuada para calcular su área y perímetro.</p><p class="subtle">Transcripción del archivo aportado: malla curricular – geometría 8° (2026)(1).docx. La versión oficial y los identificadores MEN deben verificarse por separado.</p></div>`;
const samplePaper=`<div class="paper"><p style="font:10px Arial;color:#888">DOCUMENTO SINTÉTICO · NO ES UNA ENTREGA REAL</p><h3>Áreas que habitamos</h3><p>Geometría · Grado 8.º · Período III</p><div class="line"><strong>1. Objetivo de aprendizaje</strong><p>Calcular y comparar el área y el perímetro de figuras planas en el diseño de un jardín escolar.</p></div><div class="line"><strong>2. Experiencia de aprendizaje</strong><p>En equipos, medir un espacio, dibujar su contorno y descomponerlo en rectángulos y triángulos. Justificar las unidades y comparar estrategias.</p></div><div class="line"><strong>3. Evaluación</strong><p>Entregar el diseño con los cálculos. Pendiente definir una rúbrica y una instancia de retroalimentación.</p></div><p>Haz clic en el documento para añadir un señalamiento.</p></div>`;
function review(){const r=rec();return title('02 · ESPACIO DE REVISIÓN',esc(r.title),`${esc(r.area)} · Grado ${esc(gradeLabel(r.grade,r.group))} · Período ${esc(r.period)} · ${r.id} · versión ${r.version}`,`<a class="btn" href="#historial">Ver expediente ↗</a>`)+`<div class="banner"><strong>${r.closed?'Ciclo cerrado':remaining(r)+' restantes'}</strong><span>Límite original: ${fmt(deadline(r))}. ${r.closed?'Cierre: '+fmt(r.closed):'Las solicitudes de ajustes no reinician el reloj.'}</span></div>`+stages(r)+(r.documentType?'<div class="banner"><strong>Clasificación documental: '+esc(r.documentType.label)+'</strong><span>'+esc(r.documentType.reason)+'</span></div>':'')+`<div class="review-grid"><section class="card"><div class="card-head"><h2>01 · Referencia institucional</h2></div><div class="tabs"><button data-source="pei" class="${sourceTab==='pei'?'active':''}">PEI · PDF</button><button data-source="malla" class="${sourceTab==='malla'?'active':''}">Malla</button><button data-source="otras" class="${sourceTab==='otras'?'active':''}">Otras fuentes</button></div><div id="sourceContent"></div></section><section class="card"><div class="card-head"><h2>02 · Planeación docente</h2><span class="subtle">v${r.version}</span></div><div class="doc-title"><span id="planDocName">${r.file?esc(r.file.name):'Ejemplo sintético'}</span><select id="pageSelect" aria-label="Página de la planeación">${Array.from({length:Math.max(1,r.pages.length)},(_,i)=>`<option value="${i+1}">Pág. ${i+1}</option>`).join('')}</select></div><div class="document" id="planDocument" aria-label="Planeación; clic para anotar">${r.file?'<canvas id="planCanvas"></canvas>':samplePaper}</div><div class="actions"><button class="btn small" id="addNote">＋ Añadir observación</button><button class="btn small" id="replaceFile">${r.state==='con ajustes'?'Cargar versión ajustada':r.file?'Volver a abrir PDF':'Cargar planeación nueva'}</button><input hidden type="file" id="revisionFile" accept="application/pdf,.pdf"></div><p class="subtle">Las marcas se conservan por documento, página y versión. La lectura nativa del PDF se procesa localmente.</p><div id="docStatus" role="status"></div>${r.pages.length?'<details><summary>Leer texto extraído del PDF</summary><div class="scroll">'+r.pages.map(p=>'<p class="subtle"><strong>Página '+p.page+'</strong><br>'+esc(p.text)+'</p>').join('')+'</div></details>':''}</section><aside class="card notes"><div><p class="eyebrow">APOYO A LA REVISIÓN</p><h2>Informe y evidencia</h2><p class="subtle" id="reportMeta">${r.report?'Resultado guardado · '+esc(r.report.engine):'Elige análisis de prueba o IA local.'}</p><div class="actions"><button class="btn small" id="analyze">Comprobación de prueba</button><button class="btn primary small" id="localAI">IA local</button></div><p id="analysisStatus" aria-live="polite"></p><div id="reportContent"></div></div><div><h2>Señalamientos</h2><div id="noteList"></div></div></aside></div><div class="review-footer"><label for="decisionNote" class="sr-only">Observaciones de decisión</label><textarea id="decisionNote" maxlength="4000" placeholder="Observaciones, recomendaciones y ajustes del coordinador…"></textarea><div><p class="subtle" id="decisionHelp">${['Coordinador académico'].includes(db.role)?'Toda decisión exige una observación.':'Vista de consulta. Cambia a Coordinador para probar una decisión.'}</p><div class="actions"><button class="btn danger" data-decide="devuelta">Devolver</button><button class="btn" data-decide="con ajustes">Solicitar ajustes</button><button class="btn primary" data-decide="aprobada">Aprobar ✓</button></div></div></div>`;}
function history(){const r=rec();return title('03 · EXPEDIENTE DE LA PLANEACIÓN','La historia completa, en un solo lugar.','Entregas, análisis, observaciones y decisiones conservan fecha, autor y versión.',`<button class="btn" id="exportRecord">↓ Exportar expediente JSON</button>`)+demoBanner()+`<section class="card"><div class="card-head"><h2>${esc(r.title)}</h2>${badge(r)}</div><p class="subtle">${esc(r.area)} · Grado ${esc(gradeLabel(r.grade,r.group))} · Período ${esc(r.period)} · ${r.id} · ${r.events.length} eventos · hash ${r.file?esc(r.file.hash):'no aplica al ejemplo sintético'}</p><div class="timeline">${r.events.map(e=>`<div class="event"><time>${fmt(e.at)} · ${esc(e.actor)} · v${e.version||1}</time><div><strong>${esc(e.type)}</strong><p>${esc(e.text)}</p></div></div>`).join('')}</div><div class="callout">La bitácora del navegador es editable y no constituye auditoría inviolable. Producción requiere eventos de servidor sin UPDATE/DELETE para usuarios y una copia de auditoría con controles independientes.</div></section>`;}
function timing(){const r=rec(),closed=db.records.filter(x=>x.closed);return title('04 · SEGUIMIENTO DEL PLAZO','El tiempo también se acompaña.','Rectoría y coordinación comparten la visibilidad del vencimiento original y los puntos de escalamiento.')+stats()+`<div class="two"><section class="card"><h2>${esc(r.title)}</h2><p>Límite: <strong>${fmt(deadline(r))}</strong></p><div class="progress"><span style="width:${Math.min(100,Math.max(0,(Date.now()-new Date(r.submitted))/8/DAY*100))}%"></span></div>${pipeline.map((s,i)=>{const ds=[1,5,7,8][i];return `<div class="stage"><span class="num">${i+1}</span><div><strong>${s[0]}</strong><p>${s[1]}</p></div><span class="time">${fmt(new Date(r.submitted).getTime()+ds*DAY)}</span></div>`}).join('')}<div class="callout">Supuesto: un ciclo de corrección incluido dentro de los ocho días. Si se interpreta solo como primer retorno, la institución debe ajustar esta regla explícitamente.</div></section><aside class="card prose"><h2>Avisos y escalamiento</h2><div class="note-card"><strong>24 h · Cola de análisis</strong><p>Si la IA falla, pasar a revisión humana y reintentar sin detener el plazo.</p></div><div class="note-card"><strong>Días 4 y 6 · Recordatorio</strong><p>Aviso al responsable de la etapa; sustituto asignado ante ausencia.</p></div><div class="note-card"><strong>Día 7 · Riesgo de vencimiento</strong><p>Escalar a coordinación y rectoría. Menos de 24 horas disponibles.</p></div><div class="note-card"><strong>Día 8 · Incumplimiento</strong><p>Registrar mora y abrir incidente. No generar aprobación por silencio.</p></div><button class="btn" id="requestNotification">Probar aviso del navegador</button><p class="subtle">Solo prueba visible mientras la página está abierta. Notificaciones automáticas, correo y escalamiento requieren el trabajador local.</p><h3>Indicador de rectoría</h3><p>${closed.length?Math.round(closed.filter(x=>new Date(x.closed)<=deadline(x)).length/closed.length*100)+'% de cierres dentro del plazo':'Sin cierres: indicador aún no calculable.'}</p><p>Definición: cierres oportunos / cierres del período. Pendientes vencidos se reportan aparte para evitar sesgo.</p></aside></div>`;}
const modules=[['Acceso y permisos','Supabase Auth local con cuentas institucionales, MFA para coordinación y rectoría. Roles y asignaciones en tablas administradas por TI; autorización en API y RLS, no en el selector de la interfaz.'],['Recepción y versiones','API local valida PDF/DOCX, tipo real, tamaño y malware. Almacén privado; SHA-256 y sello de tiempo del servidor. Cada reentrega crea una versión, nunca sobrescribe el original.'],['Corpus curricular','Registro por grado 1–11, área, período y vigencia: malla + plan de área + estándares MEN + PEI. Ingesta con OCR, páginas, fragmentos y hash. Un asesor valida cada versión antes de publicarla al motor.'],['Motor de análisis local','Trabajador de cola → recuperación de fragmentos → Qwen3-8B mediante Ollama → salida JSON validada. Cada hallazgo contiene evidencia de planeación y referencia curricular. Si falta fuente: «no verificable».'],['Revisión y decisiones','Vista lado a lado, informe explicable y comentarios anclados a documento, hash, versión, página y coordenadas. El coordinador confirma o descarta cada hallazgo y firma una decisión motivada.'],['Relojes y notificaciones','Vencimiento absoluto al recibir: t₀ + 192 h. Trabajador independiente cada minuto, outbox transaccional, clave de idempotencia por aviso, reintentos y escalamiento. Correo sin adjuntos ni información sensible.'],['Trazabilidad y gestión','Postgres local: expedientes, versiones, informes, comentarios, decisiones, eventos y recibos de notificación. Auditoría append-only para usuarios, respaldo cifrado, restauración ensayada e indicadores agregados de rectoría.'],['Trabajo desconectado','PWA para asesores en equipos institucionales: documentos autorizados, borradores cifrados e IndexedDB; cola de operaciones con UUID, versión base y sincronización idempotente. Conflictos: comparar y resolver, sin sobrescritura silenciosa.'],['Operación institucional','Proxy HTTPS, red segmentada, egress bloqueado para documentos y modelos, monitoreo de colas y capacidad, UPS y suplencias. Descarga inicial de modelos e imágenes en ventana administrada; después ejecución local.']];
function architecture(){return title('DISEÑO FUNCIONAL · PRELIMINAR','Una plataforma local. Una decisión humana.','Arquitectura propuesta para revisión pedagógica desde primero hasta undécimo, con IA abierta y control institucional.')+`<div class="banner warn"><strong>Alcance real</strong><span>GitHub aloja esta interfaz de demostración. El servidor institucional, Supabase local y el trabajador de IA son componentes por instalar; no se ha desplegado producción ni conectado la base de datos de cursos.</span></div><div class="flow-diagram"><div>Docente / asesor<small>Entrega y borradores PWA</small></div><span>→</span><div>API institucional + almacén privado<small>Valida, versiona y abre el reloj</small></div><div>Coordinador<small>Planeación + evidencia + decisión</small></div><span>←</span><div>Cola → OCR / RAG → IA local<small>Informe estructurado con citas</small></div><div>Docente y rectoría<small>Retroalimentación / indicadores</small></div><span>←</span><div>Eventos + outbox + temporizador<small>Notificaciones y registro de entrega</small></div></div><div class="module-grid">${modules.map((m,i)=>`<article class="card"><p class="module-index">MÓDULO ${String(i+1).padStart(2,'0')}</p><h2>${m[0]}</h2><p>${m[1]}</p></article>`).join('')}</div><div class="card prose" style="margin-top:22px"><h2>Contrato del informe pedagógico</h2><p>Identificación de expediente y versión; hash del archivo y corpus; modelo, digest y versión de prompt; fortalezas; hallazgos por objetivos, contenidos, actividades, evaluación, secuencia e inclusión; severidad, certeza declarada y evidencia textual con página; fuente curricular y fragmento; recomendación; estado de validación humana. La certeza declarada por el modelo no equivale a exactitud medida.</p><p>No se calcula un porcentaje de «coherencia» sin una rúbrica aprobada y validada. La ausencia de volúmenes en una sesión de áreas no implica incumplir todo el período: se evalúa la cobertura esperada según alcance temporal.</p><p><strong>Modelo propuesto:</strong> Qwen3-8B (licencia Apache 2.0 de sus pesos) con Ollama local. Pesos abiertos no implican que todo el proceso de entrenamiento sea abierto. Validar español pedagógico, sesgo, latencia y requisitos de hardware antes de aprobarlo.</p><div class="actions"><a class="btn" href="docs/ARQUITECTURA.md" target="_blank">Especificación técnica ↗</a><a class="btn" href="docs/CONTRATO-DATOS.sql" target="_blank">Contrato de datos preliminar ↗</a><a class="btn" href="docs/ON-PREMISE.md" target="_blank">Prueba de IA local ↗</a></div></div><h2 style="margin-top:32px">Flujos por rol</h2><div class="flow"><article class="card prose"><h2>Docente</h2><ol><li>Accede con identidad institucional; selecciona grado, área y período.</li><li>Carga archivo; confirma clasificación de privacidad. Borrador local: sin reloj oficial.</li><li>Servidor acepta, emite recibo y fija t₀. Estado <strong>cargada</strong>.</li><li><strong>En análisis por IA</strong>: extracción, recuperación y evaluación. Falla de IA no bloquea la revisión humana.</li><li>Recibe planeación y retroalimentación del coordinador hasta día 5.</li><li><strong>Con ajustes</strong>: responde comentarios y sube v2 hasta día 7, conservando t₀.</li><li>Recibe decisión <strong>aprobada</strong> o <strong>devuelta</strong> y recibo hasta día 8.</li></ol></article><article class="card prose"><h2>Coordinador y asesor</h2><ol><li>Abre bandeja ordenada por vencimiento; registra responsable y suplente.</li><li>En estado <strong>en revisión</strong>, compara versión de planeación, malla y fuentes.</li><li>Revisa citas de IA; confirma, descarta o corrige hallazgos. Documenta incertidumbre.</li><li>Añade marcas, recomendaciones y ajustes propios. Decide con motivación.</li><li>Solicita ajustes (ciclo abierto), aprueba o devuelve (retorno motivado y cierre).</li><li>Revisa v2 con comparación de versiones; comunica decisión sin cambiar el límite.</li><li>Fuera de línea: guarda borrador pendiente; al sincronizar, el servidor valida permisos, reloj y conflictos antes de confirmar.</li></ol></article><article class="card prose wide"><h2>Rectoría · vista resumida</h2><p>Autenticarse → consultar indicadores agregados y pendientes vencidos → identificar cuellos de botella → asignar suplencias y registrar escalamiento → auditar accesos e incidentes. Acceso al contenido excepcional y justificado; no acceso irrestricto por defecto a datos sensibles.</p></article></div><div class="card prose" style="margin-top:22px"><h2>Transiciones y reloj</h2><div class="table-wrap"><table><tr><th>Desde</th><th>Hacia</th><th>Actor / condición</th><th>Reloj</th></tr><tr><td>Borrador</td><td>Cargada</td><td>Servidor recibe y valida</td><td>Inicia t₀</td></tr><tr><td>Cargada</td><td>En análisis por IA</td><td>Trabajador toma tarea</td><td>Sigue</td></tr><tr><td>En análisis por IA</td><td>En revisión</td><td>Informe listo o fallo explicitado</td><td>Sigue</td></tr><tr><td>En revisión</td><td>Con ajustes</td><td>Coordinador retorna observaciones</td><td>Sigue, sin reinicio</td></tr><tr><td>Con ajustes</td><td>Cargada (v2)</td><td>Docente reentrega</td><td>Conserva t₀</td></tr><tr><td>En revisión</td><td>Aprobada / Devuelta</td><td>Decisión motivada y comunicación registrada</td><td>Cierra; demora de entrega sigue siendo incidente</td></tr></table></div></div>`;}
function wires(){const wire=(n,t,body,caption)=>`<section><div class="wire"><header><strong>IJR / ${n}</strong><span>Rol · avisos · conexión</span></header><h3>${t}</h3>${body}</div><p class="wire-caption">${caption}</p></section>`;return title('DISEÑO UX · BAJA FIDELIDAD','La estructura antes del detalle.','Seis pantallas traducibles a diseño. Los números indican jerarquía de lectura y los textos describen las interacciones.')+`<div class="wire-grid">${wire('01','Carga de planeación','<div class="row"><div class="box">Grado / Área</div><div class="box">Período / Vigencia</div></div><div class="box" style="text-align:center">[ Seleccionar PDF o DOCX ]<br>Estado de validación · privacidad · tamaño</div><span class="fakebtn">Guardar borrador</span> <span class="fakebtn">Enviar y obtener recibo →</span>','1. Identificación; 2. archivo y errores accesibles; 3. confirmación de privacidad; 4. recibo con inicio y vencimiento. El borrador no equivale a entrega.')}${wire('02','Informe de IA','<div class="box">Versión analizada · fuentes · modelo · estado</div><div class="row"><div class="box">Fortalezas</div><div class="box">Aspectos a revisar</div></div><div class="box">Hallazgo → evidencia docente + cita curricular<br>[ Ver página ] [ Confirmar / Descartar ]</div>','El resumen precede al detalle. Cada hallazgo abre una evidencia; los datos no verificables se muestran como tales. Decisiones reservadas al humano.')}${wire('03','Revisión del coordinador','<div class="box">Plazo global / tiempo de etapa / responsable</div><div class="row"><div class="box">MALLA / PEI<br>Versión · página<br>Fragmento resaltado</div><div class="box">PLANEACIÓN<br>Versión · página<br>① ② marcas</div></div><div class="box">Observación / recomendación / ajuste</div><span class="fakebtn">Devolver</span> <span class="fakebtn">Solicitar ajustes</span> <span class="fakebtn">Aprobar</span>','Dos documentos con controles independientes y panel de evidencia. Clic o botón accesible para añadir marca. En móvil, documentos apilados con acceso rápido a las fuentes.')}${wire('04','Historial de trazabilidad','<div class="box">Expediente / versión / hash / filtro por actor</div><div class="box">○ Entrega · fecha · autor<br>│<br>○ IA · modelo · informe<br>│<br>○ Coordinador · observación · decisión<br>│<br>○ Docente · respuesta · nueva versión</div><span class="fakebtn">Exportar expediente</span>','Línea de tiempo cronológica; comentarios de IA y humanos diferenciados. Versiones anteriores permanecen consultables y las marcas conservan sus anclas.')}${wire('05','Tiempos y notificaciones','<div class="row"><div class="box">Restante global</div><div class="box">Responsable actual</div></div><div class="box">D0 → D1 → D5 → D7 → D8<br>Recepción / IA / retorno / ajuste / cierre</div><div class="box">Aviso / destinatario / canal<br>En cola · enviado · entregado · error</div>','No depender solo del color: incluir estado textual y fecha absoluta. Las alertas no muestran datos sensibles. Acción explícita para abrir el expediente autenticado.')}${wire('06','Asesor fuera de línea','<div class="box">Sin conexión · última sincronización · plazo estimado</div><div class="box">Documentos habilitados para este equipo<br>Borradores pendientes: 2<br>Conflictos por resolver: 1</div><span class="fakebtn">Guardar borrador local</span> <span class="fakebtn">Sincronizar</span>','Nunca anunciar «entregado» sin recibo del servidor. Mostrar vencimiento original, cola, versión base y resolución de conflictos. Retirar caché al cerrar sesión institucional.')}</div>`;}
function privacy(){return title('VALIDACIÓN INSTITUCIONAL','Privacidad desde la primera entrega.','Diseño preventivo y decisiones pendientes. La infraestructura local por sí sola no acredita cumplimiento legal.')+`<div class="banner warn"><strong>Antes de producción</strong><span>Validación jurídica y de TI requerida. Este laboratorio público no es un canal institucional para documentos sensibles.</span></div><div class="flow"><article class="card prose"><h2>Ley 1581 de 2012</h2><p>Los datos de menores tienen protección reforzada. No todos son «sensibles» por definición legal; salud, biometría u otras categorías del artículo 5 sí pueden serlo. Debe justificarse cada finalidad y evitar incluir datos de alumnos en las planeaciones.</p><p>El tratamiento excepcional de datos de menores debe respetar el interés superior y sus derechos; requiere evaluar autorización del representante y el derecho a ser escuchado según madurez, junto con la base jurídica aplicable. Un checkbox del docente no reemplaza ese proceso.</p><ul><li>Inventario y clasificación; minimización y eliminación de identificadores antes del modelo.</li><li>Detección de datos personales + revisión de excepciones. No prometer anonimización perfecta mediante regex.</li><li>Responsable institucional definido, encargados identificados, política, finalidades y procedimiento de consultas/reclamos.</li><li>HTTPS, cifrado de discos y respaldos, MFA, control por expediente, auditoría de acceso, gestión de incidentes y secretos.</li><li>Retención aprobada por tipo documental; supresión segura y tratamiento de respaldos según obligaciones vigentes.</li><li>Sin documentos, vectores ni prompts enviados a servicios externos o publicados en GitHub. Sin entrenamiento con entregas.</li></ul><a href="https://normograma.mintic.gov.co/mintic/compilacion/docs/ley_1581_2012.htm" target="_blank" rel="noopener">Fuente: Ley 1581 (MINTIC) ↗</a><p><a href="https://sedeelectronica.sic.gov.co/publicaciones/boletin-juridico/concepto/tratamiento-excepcional-y-autorizacion-del-representante-legal-con-interes-superior" target="_blank" rel="noopener">Criterio de la SIC sobre menores ↗</a></p></article><article class="card prose"><h2>Supuestos para validar</h2><ol><li>Un ciclo de corrección dentro de los ocho días. Primer retorno hasta D5, respuesta hasta D7, cierre hasta D8.</li><li>Ocho días = 192 horas desde la aceptación del servidor, incluidos festivos y fines de semana. Mostrar hora de Bogotá; almacenar UTC.</li><li>«Devuelta» significa devolución motivada que cierra el ciclo; «con ajustes» mantiene el expediente abierto.</li><li>Archivo rechazado no inicia revisión. Debe quedar constancia del intento y un canal de contingencia para impedir que una falla tecnológica borre la fecha de entrega.</li><li>La aceptación fuera de línea solo ocurre al sincronizar; el tiempo declarado por el equipo no se acepta como sello oficial.</li><li>Asesor propone; coordinador decide; rectoría supervisa. Permisos definitivos requieren validación institucional.</li><li>Corpus completo por grado y área, modelo y rúbrica aprobados por responsables pedagógicos. No se presupone que los archivos disponibles cubran 1.º–11.º.</li><li>Retención, volúmenes, suplencias, capacidad y recuperación deben acordarse antes del piloto.</li></ol></article><article class="card prose"><h2>Riesgos sobre el plazo</h2><p>Colas de IA, ausencias, cortes de energía, días no laborales, notificaciones sin entrega, correcciones repetidas y equipos desconectados. Mitigación: límites por etapa, suplentes, UPS, revisión humana si la IA falla, outbox durable y alertas de mora.</p><p>No se puede garantizar ocho días solo mediante software. Se requiere capacidad de revisión y compromiso operativo. Si el aviso falla, registrar incidente y activar el canal alternativo, sin falsear el cierre.</p></article><article class="card prose"><h2>Riesgos de IA y datos</h2><p>Alucinación, inyección de instrucciones en documentos, OCR defectuoso, referencias antiguas, sesgos e inferencia de identidad. Separar instrucciones de evidencia, no ejecutar contenido del PDF, limitar herramientas, validar JSON y citas, y exigir revisión humana.</p><p>El acceso desconectado aumenta exposición por pérdida de equipos. Solo dispositivos administrados, cifrado, caducidad y revocación al reconectar; la revocación remota no es instantánea sin conexión.</p><p>Las copias locales de esta demo no están cifradas ni protegidas por roles. Su uso debe limitarse a documentos de prueba.</p></article></div><div class="card prose" style="margin-top:22px"><h2>Operativo en esta entrega / pendiente de instalación</h2><div class="table-wrap"><table><tr><th>Operativo en el navegador</th><th>Requiere servidor institucional</th></tr><tr><td>Cargar y visualizar PDF real; extraer texto; añadir marcas por página y versión; comentarios y decisiones de prueba; exportar historial; reloj visible; interfaz fuera de línea después de preparar caché.</td><td>Autenticación y RLS; recepción multiusuario; trazabilidad resistente a manipulación; corpus completo y RAG; IA local; correo y alertas con página cerrada; conflictos y sincronización real; controles de cumplimiento.</td></tr></table></div><p>Se incluye un adaptador de inferencia local para pruebas con Ollama; no es un backend de producción. La comprobación del navegador usa reglas explícitas y no debe presentarse como un análisis de IA.</p><button class="btn danger" id="clearDemo">Borrar datos de prueba de este dispositivo</button></div>`;}
function openDB(){return new Promise((res,rej)=>{const q=indexedDB.open('ijr-planning-pdfs',1);q.onupgradeneeded=()=>q.result.createObjectStore('files');q.onsuccess=()=>res(q.result);q.onerror=()=>rej(q.error);});}
async function fileStore(op,key,value){const d=await openDB();return new Promise((resolve,reject)=>{const tx=d.transaction('files',op==='get'?'readonly':'readwrite'),s=tx.objectStore('files'),q=op==='get'?s.get(key):op==='clear'?s.clear():s.put(value,key);let result;q.onsuccess=()=>result=q.result;tx.oncomplete=()=>{d.close();resolve(result);};tx.onerror=()=>{d.close();reject(tx.error);};});}
async function readPDF(file){if(file.size>15*1024*1024)throw Error('El archivo supera 15 MB.');const data=await file.arrayBuffer();if(new TextDecoder().decode(data.slice(0,5))!=='%PDF-')throw Error('El archivo no tiene una cabecera PDF válida.');const pdf=await pdfjs.getDocument({data:new Uint8Array(data.slice(0)),isEvalSupported:false}).promise;if(pdf.numPages>80)throw Error('Máximo 80 páginas por prueba.');const pages=[];for(let i=1;i<=pdf.numPages;i++){const p=await pdf.getPage(i);const c=await p.getTextContent();pages.push({page:i,text:c.items.map(x=>x.str).join(' ')});}const hash=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',data))).map(x=>x.toString(16).padStart(2,'0')).join('');return {pdf,data,pages,hash};}
async function paint(pdf,page,canvas){const p=await pdf.getPage(page),width=canvas.parentElement.clientWidth||450,base=p.getViewport({scale:1}),view=p.getViewport({scale:Math.min(2,devicePixelRatio||1)*width/base.width});canvas.width=view.width;canvas.height=view.height;await p.render({canvasContext:canvas.getContext('2d'),viewport:view}).promise;}
async function uploadCurriculumPdf(file){
 const r=rec();if(!file)return;
 const status=$('#curriculumStatus');
 if(status)status.textContent='Validando la estructura del PDF curricular...';
 let parsed=null;
 try{
  if(!['Coordinador académico','Asesor de área'].includes(db.role))throw Error('En esta demostración, selecciona la vista Coordinador o Asesor para vincular fuentes. No hay autenticación real.');
  parsed=await readPDF(file);
  const inspection=inspectCurriculumPdf(parsed.pages,{grade:r.grade,area:r.area,period:r.period});
  if(!inspection.accepted)throw Error('El archivo no se identificó como malla o plan de área: '+inspection.warnings.join(' '));
  await fileStore('put',parsed.hash,parsed.data);
  const key=curriculumScope(r.grade,r.area,r.period),old=curriculumRegistry[key];
  const entry={hash:parsed.hash,name:file.name,grade:r.grade,area:r.area,period:r.period,bytes:file.size,pages:parsed.pages.length,status:'pendiente',at:stamp(),signals:inspection.signals,warnings:inspection.warnings,source:'PDF aportado localmente; no verificado por la institución'};
  curriculumRegistry[key]={active:entry,history:old?[...(old.history||[]),old.active].filter(Boolean):[]};
  try{saveCurriculum();}catch(e){if(old)curriculumRegistry[key]=old;else delete curriculumRegistry[key];throw e;}
  if(activeCurriculumPdf&&activeCurriculumHash!==parsed.hash){try{await activeCurriculumPdf.destroy();}catch{}activeCurriculumPdf=null;activeCurriculumHash=null;}
  event(r,'Referencia curricular aportada','PDF: '+file.name+'; SHA-256: '+parsed.hash+'. Estado: pendiente de validación institucional.','Sistema');
  sourceTab='malla';await sourceContent();renderNotes();
  toast('Malla vinculada al grado, asignatura y período. Falta validación institucional.');
 }catch(e){if(status&&status.isConnected)status.textContent=e.message;toast(e.message);}
 finally{if(parsed)try{await parsed.pdf.destroy();}catch{}}
}
async function sourceContent(){
 const c=$('#sourceContent');if(!c)return;
 const r=rec();
 if(sourceTab==='malla'){
  const ref=mallaFor(r),key=curriculumScope(r.grade,r.area,r.period);
  let html='<div class="source-excerpt"><h3>Referencia de malla curricular</h3><p><strong>Ámbito:</strong> '+esc(r.area)+' · Grado '+esc(r.grade)+'.º · Período '+esc(r.period)+'. Aplica a los grupos A, B y C salvo que la institución establezca otra malla.</p>';
  if(ref){
   html+='<p><strong>'+esc(displaySource(ref))+'</strong></p><p>'+esc(ref.name)+' · SHA-256: <code>'+esc(ref.hash.slice(0,14))+'…</code></p><p>'+esc(ref.source)+'</p>';
   html+='<ul>'+ref.warnings.map(w=>'<li>'+esc(w)+'</li>').join('')+'</ul></div>';
   html+='<div class="doc-title"><span>PDF original · '+esc(ref.pages)+' páginas</span><select id="mallaPageSelect" aria-label="Página de la malla">'+Array.from({length:ref.pages},(_,i)=>'<option value="'+(i+1)+'">Pág. '+(i+1)+'</option>').join('')+'</select></div>';
   html+='<div id="sourceDocument" class="document notranslate" data-source-kind="malla" translate="no" aria-label="Malla original; clic para anotar"><canvas id="sourceCanvas"></canvas></div>';
  }else{
   html+='<div class="banner warn"><strong>Sin malla institucional aportada</strong><span>No se puede confirmar alineación curricular por ausencia de una fuente original para esta combinación. No se sustituye con documentos de otra institución.</span></div></div>';
  }
  html+='<div class="source-upload"><label for="mallaPdfFile">Vincular o actualizar PDF original de malla / plan de área</label><input id="mallaPdfFile" type="file" accept="application/pdf,.pdf" aria-describedby="curriculumStatus"><p class="subtle">Este registro se guarda solo en este navegador, para el grado/asignatura/período seleccionados. El archivo debe ser revisado y aprobado institucionalmente antes de usarlo como fuente oficial.</p><p id="curriculumStatus" role="status"></p></div>';
  c.innerHTML=html;
  const file=$('#mallaPdfFile');if(file)file.onchange=e=>uploadCurriculumPdf(e.target.files?.[0]);
  if(ref){
   const select=$('#mallaPageSelect');const sourceCanvas=$('#sourceCanvas');
   if(select)select.onchange=async()=>{if(activeCurriculumPdf&&sourceCanvas?.isConnected){await paint(activeCurriculumPdf,Number(select.value),sourceCanvas);renderNotes();}};
   try{
    if(!activeCurriculumPdf||activeCurriculumHash!==ref.hash){
     const data=await fileStore('get',ref.hash);
     if(!data)throw Error('PDF de malla no disponible en este dispositivo. Debe vincularse nuevamente.');
     activeCurriculumPdf=await pdfjs.getDocument({data:new Uint8Array(data),isEvalSupported:false}).promise;activeCurriculumHash=ref.hash;
    }
    if(sourceTab==='malla'&&sourceCanvas?.isConnected){await paint(activeCurriculumPdf,1,sourceCanvas);renderNotes();}
   }catch(e){if($('#curriculumStatus'))$('#curriculumStatus').textContent=e.message;}
  }else renderNotes();
  return;
 }
 if(sourceTab==='otras'){
  c.innerHTML='<div class="source-excerpt"><h3>Documentos de referencia</h3><p>El PEI 2026 es una fuente institucional real; no sustituye las mallas específicas. Solo puede verificarse alineación curricular con la malla original, su vigencia, grado, asignatura y período.</p><p>Las referencias MEN o documentos de otras instituciones no se presentan como mallas del IJR.</p></div>';
  return;
 }
 c.innerHTML='<div class="doc-title"><span>PEI IJR 2026 · original p. 41 · extracto</span><a href="docs/pei-extracto-p41.pdf" target="_blank" rel="noopener">Abrir PDF ↗</a></div><div class="document notranslate" id="sourceDocument" data-source-kind="pei" translate="no" aria-label="PEI 2026; clic para anotar"><canvas id="sourceCanvas"></canvas><div class="highlight" style="left:13%;top:35%;width:77%;height:26%"></div></div><p class="subtle">Fuente institucional PEI 2026, §2.5.3, página original 41. El resaltado no es una observación; haz clic en el PDF para anotar.</p>';
 try{
  sourcePdf??=await pdfjs.getDocument({url:'docs/pei-extracto-p41.pdf',isEvalSupported:false}).promise;
  if(sourceTab==='pei'&&$('#sourceCanvas')){await paint(sourcePdf,1,$('#sourceCanvas'));renderNotes();}
 }catch(e){if(c.isConnected)c.innerHTML='<p>No se pudo abrir el PEI. Abre el PDF desde el enlace disponible en la página.</p>';}
}
function renderNotes(){const r=rec(),el=$('#noteList');if(!el)return;el.innerHTML=r.notes.length?r.notes.map((n,i)=>`<div class="note-card"><button class="btn small" data-note="${i}">${i+1} · ${n.document==='fuente'?'PEI':'Planeación'} · p. ${n.page} · v${n.version}</button><p>${esc(n.text)}</p><small>${esc(n.actor)} · ${fmt(n.at)}</small></div>`).join(''):'<p class="subtle">Haz clic sobre la planeación o usa «Añadir observación».</p>';document.querySelectorAll('#planDocument .pin').forEach(x=>x.remove());r.notes.forEach((n,i)=>{if(n.version!==r.version||n.page!==Number($('#pageSelect')?.value||1)||n.document==='fuente')return;const b=document.createElement('button');b.className='pin';b.textContent=i+1;b.style.left=n.x*100+'%';b.style.top=n.y*100+'%';b.title=n.text;b.setAttribute('aria-label',`Señalamiento ${i+1}: ${n.text}`);b.onclick=e=>{e.stopPropagation();toast(n.text);};$('#planDocument')?.append(b);});}
function report(){const r=rec(),el=$('#reportContent');if(!el)return;if(!r.report){el.innerHTML='<div class="callout">Aún no hay informe. La comprobación de prueba busca términos en el texto; la IA local requiere el adaptador instalado.</div>';return;}el.innerHTML=`<div class="callout">${esc(r.report.scope||'Revisar evidencia y fuentes antes de decidir.')}</div>${r.report.findings.map((f,i)=>`<div class="note-card"><strong>${i+1}. ${esc(f.title)}</strong><p>${esc(f.detail)}</p><small>${esc(f.source||'Sin referencia validada')} · p. ${f.page||1}</small><div class="actions" style="margin-top:8px"><button class="btn small" data-evidence="${f.page||1}">Ver evidencia</button>${f.verdict?`<small>${esc(f.verdict)}</small>`:`<button class="btn small" data-finding="${i}" data-verdict="Confirmado">Confirmar</button><button class="btn small" data-finding="${i}" data-verdict="Descartado">Descartar</button>`}</div></div>`).join('')}`;}
async function loadActive(){const seq=++renderSeq,r=rec();activePdf=null;if(!r.file){renderNotes();return;}try{const data=await fileStore('get',r.file.hash);if(!data)throw Error('El PDF no está en este dispositivo. Usa «Volver a abrir PDF».');const pdf=await pdfjs.getDocument({data:new Uint8Array(data),isEvalSupported:false}).promise;if(seq!==renderSeq)return;activePdf=pdf;await paint(pdf,1,$('#planCanvas'));renderNotes();}catch(e){if($('#docStatus'))$('#docStatus').textContent=e.message;}}
function addAnchor(x=.5,y=.5){if(rec().closed){toast('El ciclo está cerrado; consulta el historial.');return;}pendingAnchor={x,y,page:Number($('#pageSelect')?.value||1),version:rec().version,document:'planeacion',hash:rec().file?.hash||'sintetico-v1'};$('#anchorInfo').textContent=`Planeación · página ${pendingAnchor.page} · versión ${pendingAnchor.version}`;$('#annotationText').value='';$('#annotationDialog').showModal();$('#annotationText').focus();}
async function analyze(local=false){const r=rec(),old=r.state;if(!['cargada','en revisión'].includes(old)){toast('El análisis requiere una entrega cargada o en revisión.');return;}if(r.file&&classifyDocument(r.pages).type!=='planeacion'){toast('Archivo no verificado como planeación. No se genera informe pedagógico.');return;}if(r.file&&!r.pages.some(p=>p.text.trim())){toast('PDF sin texto. Se necesita OCR local antes de analizar.');return;}r.state='en análisis por IA';event(r,'Análisis iniciado',local?'Solicitud de IA al adaptador local.':'Comprobación determinista de prueba; no es IA.','Sistema');const status=$('#analysisStatus');status.textContent=local?'Consultando el modelo local…':'Comprobando el texto…';$('#analyze').disabled=true;$('#localAI').disabled=true;try{const pages=r.pages.length?r.pages:[{page:1,text:'Objetivo calcular áreas y perímetros. Actividad medir y comparar en equipo. Evaluación entregar diseño; pendiente rúbrica.'}];let findings,engine,scope;if(local){if(!['localhost','127.0.0.1'].includes(location.hostname))throw Error('La IA se ejecuta desde el servidor local. Abre docs/ON-PREMISE.md e inicia el adaptador; GitHub Pages no puede ejecutarla.');const response=await fetch('/api/analyze',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({pages,area:r.area,grade:r.grade,period:r.period}),signal:AbortSignal.timeout(180000)});const out=await response.json();if(!response.ok)throw Error(out.error||'Error de inferencia');if(!Array.isArray(out.findings))throw Error('El modelo no devolvió un informe válido.');findings=out.findings;engine=out.engine;scope='Inferencia local real. Requiere validación humana; corpus de prueba limitado al PEI.';}else{engine='Reglas explícitas del navegador · sin IA';scope='Detección de menciones, no valoración pedagógica. Una palabra encontrada no demuestra alineación ni cumplimiento.';findings=[['Objetivos','objetiv|propósito|aprendizaje'],['Actividades','actividad|experiencia|taller|medir'],['Evaluación','evaluaci|rúbrica|rubrica|criterio']].map(([title,pattern])=>{const p=pages.find(p=>new RegExp(pattern,'i').test(p.text));return {title,detail:p?'Mención localizada: «'+p.text.slice(Math.max(0,p.text.search(new RegExp(pattern,'i'))-30),Math.max(0,p.text.search(new RegExp(pattern,'i'))-30)+180)+'». Verificar contexto, alcance y calidad.':'Sin mención detectada por la regla; verificar manualmente. No constituye un error confirmado.',page:p?.page||1,source:'Planeación cargada · búsqueda textual'};});findings.push({title:'Alineación curricular pendiente',detail:'Comparar evidencia con la malla vigente, el plan de área, los estándares y el PEI. No se ha ejecutado una evaluación semántica.',page:1,source:'PEI 2026 §2.5.3 · p. original 41; malla según grado/área'});}r.report={engine,scope,findings,at:stamp(),version:r.version};r.reports??=[];r.reports.push(r.report);r.state='en revisión';event(r,'Informe disponible',`${engine}. ${findings.length} apartados; validación humana pendiente.`,'Sistema');report();status.textContent='Informe guardado. Revisión humana requerida.';}catch(e){r.state=old;event(r,'Fallo de análisis',e.message,'Sistema');status.textContent=e.message;}finally{if($('#analyze'))$('#analyze').disabled=false;if($('#localAI'))$('#localAI').disabled=false;document.querySelectorAll('[data-decide]').forEach(b=>b.disabled=db.role!=='Coordinador académico'||r.state!=='en revisión');document.querySelectorAll('.steps span').forEach((s,i)=>s.classList.toggle('current',states[i]===r.state));if($('#reportMeta')&&r.report)$('#reportMeta').textContent='Resultado guardado · '+r.report.engine;save();}}
async function doUpload(e){e.preventDefault();const b=$('#uploadSubmit');b.disabled=true;$('#fileStatus').textContent='Validando PDF y extrayendo texto…';try{const area=normalizeSubject($('#area').value,$('#otherArea').value),group=normalizeGroup($('#group').value);const file=$('#pdfFile').files[0],p=await readPDF(file);const classification=classifyDocument(p.pages);if(classification.type!=='planeacion'){p.pdf.destroy();throw Error(classification.label+'. '+classification.reason+' No se ha registrado el archivo.');}await fileStore('put',p.hash,p.data);const r={id:'PL-'+Date.now().toString(36).toUpperCase(),title:$('#planTitle').value.trim(),grade:$('#grade').value,group,area,period:$('#period').value,author:$('#author').value.trim(),state:'cargada',submitted:stamp(),version:1,documentType:classification,file:{name:file.name,hash:p.hash,size:file.size},pages:p.pages,notes:[],report:null,events:[]};db.records.unshift(r);db.selected=r.id;event(r,navigator.onLine?'Entrega de prueba guardada':'Borrador sin conexión guardado','Registro local de demostración; no es recibo de servidor institucional.','Docente · demo');event(r,'Clasificación documental',classification.label+' — '+classification.reason,'Sistema');if(!p.pages.some(x=>x.text.trim()))event(r,'OCR requerido','No hay texto extraíble; la revisión manual sigue disponible.','Sistema');p.pdf.destroy();location.hash='revision';}catch(e){$('#fileStatus').textContent=e.message;b.disabled=false;}}
async function replacePDF(file){const r=rec();if(!file)return;try{const p=await readPDF(file);const classification=classifyDocument(p.pages);if(classification.type!=='planeacion'){p.pdf.destroy();throw Error(classification.label+'. '+classification.reason+' No se vinculó el archivo.');}if(r.state!=='con ajustes'&&r.file&&r.file.hash!==p.hash)throw Error('El archivo es diferente al original. Solicita ajustes para registrar una nueva versión.');if(r.state==='con ajustes'){if(r.file?.hash===p.hash)throw Error('Selecciona un archivo ajustado diferente de la versión anterior.');r.versions??=[];r.versions.push({version:r.version,file:r.file,pages:r.pages,report:r.report});r.version++;r.report=null;r.state='cargada';}await fileStore('put',p.hash,p.data);r.file={name:file.name,hash:p.hash,size:file.size};r.pages=p.pages;r.documentType=classification;event(r,'Clasificación documental',classification.label+' — '+classification.reason,'Sistema');event(r,'Archivo disponible',`Documento vinculado a v${r.version}; plazo original conservado.`);p.pdf.destroy();render();}catch(e){toast(e.message);}}
function decide(state){const r=rec(),text=$('#decisionNote').value.trim();if(db.role!=='Coordinador académico'){toast('Selecciona la vista Coordinador para probar esta acción.');return;}if(r.state!=='en revisión'){toast('Primero completa o registra la revisión de la entrega.');return;}if(!text){$('#decisionNote').focus();toast('Escribe una observación antes de decidir.');return;}r.state=state;if(['aprobada','devuelta'].includes(state))r.closed=stamp();event(r,state==='con ajustes'?'Ajustes solicitados':state==='aprobada'?'Aprobación registrada':'Devolución motivada',text);event(r,'Aviso local creado','Notificación de prueba disponible en este navegador; envío y entrega institucional pendientes.','Sistema');render();toast('Decisión guardada en el expediente de prueba.');}
function exportRecord(){const r=rec(),blob=new Blob([JSON.stringify({exported:stamp(),warning:'Expediente de demostración; no es auditoría de servidor.',...r},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`${r.id}-expediente.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function render(){++renderSeq;const view=location.hash.slice(1)||'bandeja',routes={bandeja:inbox,cargar:upload,revision:review,historial:history,tiempos:timing,arquitectura:architecture,wireframes:wires,garantias:privacy};$('#main').innerHTML=(routes[view]||inbox)();document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===view));$('#inboxCount').textContent=db.records.filter(x=>!x.closed).length;
if(view==='bandeja'){table();$('#search').oninput=table;$('#stateFilter').onchange=table;}
if(view==='cargar'){$('#uploadForm').onsubmit=doUpload;const updateOtherArea=()=>{const other=$('#area').value==='Otra asignatura';$('#otherAreaWrap').hidden=!other;$('#otherArea').required=other;};$('#area').onchange=updateOtherArea;updateOtherArea();$('#pdfFile').onchange=async e=>{const file=e.target.files?.[0],status=$('#fileStatus');if(!file){status.textContent='';return;}status.textContent='Identificando tipo documental…';try{const p=await readPDF(file);const classification=classifyDocument(p.pages);p.pdf.destroy();if(status.isConnected&&$('#pdfFile')?.files?.[0]===file)status.textContent=classification.label+'. '+classification.reason+(classification.type==='planeacion'?' Puedes continuar la entrega.':' No se registrará como planeación.');}catch(error){if(status.isConnected&&$('#pdfFile')?.files?.[0]===file)status.textContent=error.message;}};}
if(view==='revision'){sourceContent();loadActive();report();renderNotes();$('#addNote').onclick=()=>addAnchor();$('#planDocument').onclick=e=>{if(e.target.closest('button'))return;const b=$('#planDocument').getBoundingClientRect();addAnchor((e.clientX-b.left)/b.width,(e.clientY-b.top)/b.height);};$('#pageSelect').onchange=async()=>{if(activePdf)await paint(activePdf,Number($('#pageSelect').value),$('#planCanvas'));renderNotes();};$('#replaceFile').onclick=()=>{if(!r.file&&r.state!=='con ajustes'){location.hash='cargar';return;}$('#revisionFile').click();};$('#revisionFile').onchange=e=>replacePDF(e.target.files[0]);$('#analyze').onclick=()=>analyze();$('#localAI').onclick=()=>analyze(true);document.querySelectorAll('[data-decide]').forEach(b=>{b.disabled=db.role!=='Coordinador académico'||rec().state!=='en revisión';b.onclick=()=>decide(b.dataset.decide);});}
if(view==='historial')$('#exportRecord').onclick=exportRecord;
if(view==='tiempos')$('#requestNotification').onclick=async()=>{if(!('Notification'in window)){toast('Este navegador no ofrece notificaciones.');return;}try{const p=await Notification.requestPermission();if(p==='granted')new Notification('Planning Hub · prueba',{body:'Revisa el plazo de tu planeación. Aviso local de demostración.'});else toast('Permiso no concedido; los avisos siguen visibles en el panel.');}catch{toast('Las notificaciones requieren HTTPS y soporte del navegador.');}};
if(view==='garantias')$('#clearDemo').onclick=async()=>{if(!confirm('¿Borrar todos los expedientes de prueba y PDF guardados en este navegador?'))return;localStorage.removeItem(KEY);await fileStore('clear');location.reload();};}
document.addEventListener('click',e=>{const open=e.target.closest('[data-open]');if(open){db.selected=open.dataset.open;save();location.hash='revision';}const src=e.target.closest('[data-source]');if(src){sourceTab=src.dataset.source;document.querySelectorAll('[data-source]').forEach(b=>b.classList.toggle('active',b===src));sourceContent();}const ev=e.target.closest('[data-evidence]');if(ev){$('#pageSelect').value=Math.min(Number(ev.dataset.evidence),Math.max(1,rec().pages.length));$('#pageSelect').dispatchEvent(new Event('change'));$('#planDocument').scrollIntoView({behavior:'smooth',block:'center'});}const f=e.target.closest('[data-finding]');if(f){const item=rec().report.findings[Number(f.dataset.finding)];item.verdict=f.dataset.verdict;event(rec(),'Hallazgo validado',`${item.title}: ${item.verdict}.`);report();}const n=e.target.closest('[data-note]');if(n){const a=rec().notes[Number(n.dataset.note)];if(a.version!==rec().version){toast('Marca de una versión anterior: consulta la versión exportada en el expediente.');return;}$('#pageSelect').value=a.page;$('#pageSelect').dispatchEvent(new Event('change'));toast(a.text);}});
$('#annotationForm').onsubmit=e=>{e.preventDefault();const r=rec(),text=$('#annotationText').value.trim();if(!text)return;r.notes.push({...pendingAnchor,text,at:stamp(),actor:db.role});event(r,'Señalamiento añadido',`p. ${pendingAnchor.page}, v${pendingAnchor.version}: ${text}`);$('#annotationDialog').close();renderNotes();};$('#cancelAnnotation').onclick=()=>$('#annotationDialog').close();$('#role').value=db.role;$('#role').onchange=()=>{db.role=$('#role').value;save();render();};window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0);});function connection(){$('#connection').textContent=navigator.onLine?'En línea · demo local':'Sin conexión · sin sincronizar';}window.addEventListener('online',connection);window.addEventListener('offline',connection);connection();setInterval(()=>document.querySelectorAll('[data-clock]').forEach(x=>{const r=db.records.find(r=>r.id===x.dataset.clock);x.textContent=r.closed?'Ciclo cerrado':remaining(r);}),30000);render();if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').then(()=>navigator.serviceWorker.ready).then(()=>toast('Caché preparada para pruebas sin conexión.')).catch(()=>{});
